def gen(rng):
    def fmt(n, edges, x, sp):
        lines = [str(n)] + [f'{u} {v} {w}' for u, v, w in edges] + [str(x), str(len(sp)) + ' ' + ' '.join(map(str, sp))]
        return '\n'.join(lines)
    def tree(n, kind, wmax):
        perm = list(range(n))
        rng.shuffle(perm)
        edges = []
        for i in range(1, n):
            if kind == 'path':
                p = i - 1
            elif kind == 'star':
                p = 0
            elif kind == 'cat':
                p = i - 1 if i % 2 else max(0, i - 2)
            else:
                p = rng.randrange(i)
            u, v = perm[i], perm[p]
            if rng.random() < 0.5:
                u, v = v, u
            edges.append((u, v, rng.randint(1, wmax)))
        rng.shuffle(edges)
        return edges
    tests = [fmt(1, [], 0, [0]),
             fmt(2, [(0, 1, 7)], 1, [0]),
             fmt(2, [(0, 1, 7)], 0, [0, 1]),
             fmt(4, [(0, 1, 5), (0, 2, 5), (0, 3, 5)], 1, [1, 2, 3]),
             fmt(5, [(0, 1, 2), (1, 2, 3), (1, 3, 1), (3, 4, 4)], 2, [0, 4]),
             fmt(6, [(i, i + 1, 1) for i in range(5)], 3, [0, 5])]
    for n in (3, 4, 5, 6, 8, 10, 12):
        for kind in ('rand', 'path', 'star', 'cat', 'rand'):
            k = rng.randint(1, n)
            sp = rng.sample(range(n), k)
            tests.append(fmt(n, tree(n, kind, rng.choice([1, 5, 20])), rng.randrange(n), sp))
    N = 10**5
    for kind, k in (('rand', N), ('rand', 1), ('path', N), ('path', N // 2), ('star', 1000), ('cat', 50000), ('rand', 70000)):
        tests.append(fmt(N, tree(N, kind, 10**4), rng.randrange(N), rng.sample(range(N), k)))
    return tests

